role_catalog = {
    "database_administrator": (
        "manages backups, permissions and uptime of production databases",
        "Azure SQL Database",
    ),
    "data_engineer": (
        "builds pipelines that extract, transform and load data between systems",
        "Azure Data Factory",
    ),
    "data_analyst": (
        "turns raw data into reports and visualizations for decision-making",
        "Power BI",
    ),
}

task_to_role = {
    "backup": "database_administrator",
    "grant_permission": "database_administrator",
    "build_pipeline": "data_engineer",
    "clean_data": "data_engineer",
    "build_dashboard": "data_analyst",
    "explore_trends": "data_analyst",
}

def recommend(task):
    role = task_to_role[task]
    responsibility, service = role_catalog[role]
    return role, service

for task in ["backup", "build_pipeline", "build_dashboard"]:
    role, service = recommend(task)
    print(f"{task}: role={role}, service={service}")
